package io.coolbox.timeseries;
import com.sun.jna.Pointer; import com.sun.jna.StringArray; import com.sun.jna.ptr.DoubleByReference; import com.sun.jna.ptr.LongByReference; import io.coolbox.internal.ErrorBuffer; import io.coolbox.internal.Matrices; import io.coolbox.internal.NativeHandle; import java.util.List;
/** Multivariate time-series observations (Python: {@code time_series.MultivariatTimeSeries}). */
public final class MultivariateTimeSeries extends NativeHandle {
 private static final TimeseriesNative N=TimeseriesNative.INSTANCE;
 public MultivariateTimeSeries(double[][] data){this(data,null,null);} public MultivariateTimeSeries(double[][] data,List<String> featureNames,List<String> timestamps){super(create(data,featureNames,timestamps),N::coolbox_multits_free);}
 private static Pointer create(double[][] d,List<String> featureNames,List<String> timestamps){if(d.length==0)throw new IllegalArgumentException("data must contain features");int samples=d[0].length;for(double[] r:d)if(r.length!=samples)throw new IllegalArgumentException("features must have equal sample counts");StringArray names=featureNames==null?null:new StringArray(featureNames.toArray(new String[0]));StringArray stamps=timestamps==null?null:new StringArray(timestamps.toArray(new String[0]));ErrorBuffer e=new ErrorBuffer();return e.check(N.coolbox_multits_new(Matrices.flatten(d),d.length,samples,names,names==null?0:featureNames.size(),stamps,stamps==null?0:timestamps.size(),e.pointer(),e.capacity()));}
 private MultivariateTimeSeries(Pointer h){super(h,N::coolbox_multits_free);}
 public int numFeatures(){return Math.toIntExact(N.coolbox_multits_features(handle()));} public int numSamples(){return Math.toIntExact(N.coolbox_multits_samples(handle()));}
 public double[][] data(){int f=numFeatures(),s=numSamples();double[] v=new double[f*s];ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_multits_data(handle(),v,v.length,e.pointer(),e.capacity()));return Matrices.unflatten(v,f,s);}
 public double[] feature(int i){double[] v=new double[numSamples()];ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_multits_feature(handle(),i,v,v.length,e.pointer(),e.capacity()));return v;}
 public double[] sample(int i){LongByReference n=new LongByReference();ErrorBuffer e=new ErrorBuffer();Pointer p=e.check(N.coolbox_multits_sample(handle(),i,n,e.pointer(),e.capacity()));return Matrices.takeDoubles(p,n.getValue());}
 public double at(int feature,int sample){DoubleByReference r=new DoubleByReference();ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_multits_at(handle(),feature,sample,r,e.pointer(),e.capacity()));return r.getValue();}
 public double[] means(){return stats(0);} public double[] stds(){return stats(1);} private double[] stats(int mode){LongByReference n=new LongByReference();ErrorBuffer e=new ErrorBuffer();Pointer p=e.check(N.coolbox_multits_stats(handle(),mode,n,e.pointer(),e.capacity()));return Matrices.takeDoubles(p,n.getValue());}
 public MultivariateTimeSeries normalize(){return transform(0);} public MultivariateTimeSeries minMaxScale(){return transform(1);} private MultivariateTimeSeries transform(int x){ErrorBuffer e=new ErrorBuffer();return new MultivariateTimeSeries(e.check(N.coolbox_multits_transform(handle(),x,e.pointer(),e.capacity())));}
 public double[][][] createWindows(int width){return createWindows(width,1);} public double[][][] createWindows(int width,int stride){ErrorBuffer e=new ErrorBuffer();int count=Math.toIntExact(N.coolbox_multits_window_count(handle(),width,stride,e.pointer(),e.capacity()));e.throwIfSet();int f=numFeatures();double[] flat=new double[count*f*width];e.check(N.coolbox_multits_windows(handle(),width,stride,flat,flat.length,e.pointer(),e.capacity()));double[][][] out=new double[count][f][width];int k=0;for(int w=0;w<count;w++)for(int i=0;i<f;i++)for(int j=0;j<width;j++)out[w][i][j]=flat[k++];return out;}
}

